export const LPS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/lps-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getLpsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(LPS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
